code.source:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v;
    v.push_back(10);
    v.push_back(20);
    v.push_back(30);
    cout << v.size() << endl;
    cout << v[1] << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {4, 8, 15};
    v.push_back(16);
    for (int x : v) {
        cout << x << " ";
    }
    cout << endl;
    cout << v.back() << endl;
    v.pop_back();
    cout << v.size() << endl;
    return 0;
}

